def rot90(m): return [list(r) for r in zip(*m[::-1])]
def mir(m): return [r[::-1] for r in m]
def transforms(m):
    res={}
    t=m
    for k in range(4):
        res[('r',k)]=t
        res[('m',k)]=mir(t)
        t=rot90(t)
    return res
